// End-to-end pipeline test on synthetic footage generated by FFmpeg.
// Requires ffmpeg/ffprobe on PATH. Run: node --test test/
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtemp, mkdir, copyFile, readFile, readdir, rm } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { createService } from '../src/server/lib/service.js'
import { createTools, approvalFor } from '../src/server/lib/tools.js'

const here = path.dirname(fileURLToPath(import.meta.url))
import { ensureFixtures } from './make-fixtures.mjs'
const fixtures = ensureFixtures()

const STORYBOARD = `# 分镜脚本 v1
| 镜号 | 时长 | 画面描述 | 台词/旁白 | 所需标签 | 景别 | 运镜 | 备注 |
|---|---|---|---|---|---|---|---|
| 01 | 2s | 彩色测试图开场 | 秋天的东湖，适合慢下来 | 测试图,开场 | 全景 | 固定 | |
| 02 | 2s | 彩条转场 | — | 彩条 | 全景 | 固定 | |
| 03 | 2s | 平移镜头 | 今天不赶路 | 测试图,推 | 中景 | 推 | |
| 04 | 3s | 芦苇逆光空镜 | — | 芦苇,转场空镜 | 特写 | 固定 | |
| 05 | 2s | 没有标签的镜头 | — |  | 远景 | 固定 | |
`

async function waitFor(started) {
  return started.done
}

test('media pipeline: import → clean → split → tag → match → timeline → render', { timeout: 600_000 }, async () => {
  const home = await mkdtemp(path.join(os.tmpdir(), 'mw-home-'))
  const dir = await mkdtemp(path.join(os.tmpdir(), 'mw-proj-'))
  await mkdir(path.join(dir, '原始素材库'), { recursive: true })
  for (const name of await readdir(fixtures)) if (/^C\d+\.MP4$/.test(name)) await copyFile(path.join(fixtures, name), path.join(dir, '原始素材库', name))
  const service = createService({ home })
  try {
    const { project, created } = await service.createProject({ path: dir, name: '测试项目', template: 'vlog-base' })
    assert.equal(created, true)
    for (const sub of ['原始素材库', '输出素材库/切片素材', '输出素材库/成片', '创意剪辑', '.dsh/tags']) assert.ok(existsSync(path.join(dir, sub)), sub)
    assert.ok(!existsSync(path.join(dir, '标签管理')))
    const id = project.id

    // Import
    const imported = await waitFor(await service.runStep(id, 'import'))
    assert.equal(imported.status, 'done', imported.error)
    assert.equal(imported.result.total, 7)
    assert.equal(imported.result.unsupported, 1)

    // Clean
    const cleaned = await waitFor(await service.runStep(id, 'clean'))
    assert.equal(cleaned.status, 'done', cleaned.error)
    const { root } = await service.open(id)
    const index = await service.indexStore.read(root)
    const status = Object.fromEntries(Object.values(index.raws).map((r) => [r.id, { status: r.status, reason: r.clean?.reasons?.[0]?.code, metrics: { s: r.clean?.sharpness, sh: r.clean?.shakeVariance, b: r.clean?.blackRatio } }]))
    console.log(JSON.stringify(status))
    assert.equal(status.C0001.status, 'kept')
    assert.equal(status.C0002.reason, 'blur')
    assert.equal(status.C0003.reason, 'shake')
    assert.equal(status.C0004.reason, 'black')
    assert.equal(status.C0005.reason, 'short')
    assert.equal(status.C0006.reason, 'duplicate')
    assert.equal(status.C0007.status, 'kept', 'a smooth pan is not shake')
    const report = JSON.parse(await readFile(path.join(dir, '.dsh', 'tags', '清洗报告.json'), 'utf8'))
    assert.equal(report.kept + report.rejected + report.pending, report.imported)
    assert.ok(report.details.every((d) => /\d/.test(d.evidence)), 'every discard has numeric evidence')
    assert.ok(existsSync(path.join(dir, '.dsh', 'tags', '丢弃登记', 'C0002.json')))
    assert.ok(existsSync(path.join(dir, '原始素材库', 'C0002.MP4')), 'raw is never moved')

    // Restore
    await service.media.restore(root, project.id ? (await service.open(id)).project : null, ['C0002'])
    const afterRestore = await service.media.computeReport(root, (await service.open(id)).project)
    assert.equal(afterRestore.kept, report.kept + 1)
    assert.equal(afterRestore.rejected, report.rejected - 1)

    // Before splitting, tag samples come from the raw footage.
    const rawSamples = await service.media.samples({ root, limit: 2 })
    assert.equal(rawSamples.kind, 'raws')
    assert.equal(rawSamples.items.length, 2)
    assert.ok(rawSamples.items.every((s) => s.image && existsSync(path.join(dir, s.image))), JSON.stringify(rawSamples.items))

    // Split
    const split = await waitFor(await service.runStep(id, 'split'))
    assert.equal(split.status, 'done', split.error)
    const idx2 = await service.indexStore.read(root)
    const c1 = Object.values(idx2.clips).filter((c) => c.rawId === 'C0001')
    assert.equal(c1.length, 2, 'scene change splits C0001 in two')
    for (const clip of Object.values(idx2.clips)) assert.ok(existsSync(path.join(dir, clip.proxy)) && existsSync(path.join(dir, clip.thumb)))

    // Dictionary + tags (via the Agent tools)
    const tools = Object.fromEntries(createTools(service).map((t) => [t.name, t]))
    const exec = (name, args) => ({ name, arguments: args, agent: { session: { header: { cwd: dir } } }, signal: new AbortController().signal })
    const call = (name, args = {}) => tools[name].execute(args, exec(name, args))
    // The AI looks at footage samples, suggests tags (→ 待审), the user approves them.
    const samples = await call('media_tag_samples', { limit: 3 })
    assert.equal(samples.kind, 'clips')
    assert.equal(samples.samples.length, 3)
    assert.ok(existsSync(path.join(dir, samples.samples[0].image)))
    await assert.rejects(() => call('media_creative_write', { file: '标签字典.yaml', content: 'x: []' }), /标签字典不能整份改写/)
    const sug = await call('media_tags_suggest', { items: [{ tag: '测试图', dim: '场景' }, { tag: '彩条', dim: '场景' }, { tag: '全景', dim: '景别' }] })
    assert.deepEqual(sug.added.map((t) => t.tag), ['测试图', '彩条'])
    assert.equal(sug.skipped[0].tag, '全景', 'template tags are not suggested again')
    const pendingNow = (await service.overview(id)).material.tags.pending
    assert.deepEqual(pendingNow.map((p) => [p.tag, p.suggestedDim]), [['测试图', '场景'], ['彩条', '场景']])
    const approved = await service.tagOperation(id, { ops: pendingNow.map((p) => ({ op: 'approve', tag: p.tag, dim: p.suggestedDim })) })
    assert.match(approved.summary, /2 项标签操作/)
    const dictDoc = await service.creative.read(root, '标签字典.yaml')
    assert.match(dictDoc.content, /场景: \[测试图, 彩条\]/)
    assert.match(dictDoc.content, /待审: \[\]/)
    const kf = await call('media_keyframes', {})
    assert.ok(kf.clips.length >= 4)
    assert.ok(existsSync(path.join(dir, kf.clips[0].image)))
    const items = kf.clips.map((c) => {
      if (c.clipId === 'C0001_s01') return { clipId: c.clipId, tags: [{ tag: '测试图', confidence: 0.9 }, { tag: '全景', confidence: 0.9 }, { tag: '固定', confidence: 0.9 }, { tag: '开场', confidence: 0.7 }] }
      if (c.clipId === 'C0001_s02') return { clipId: c.clipId, tags: [{ tag: '彩条', confidence: 0.95 }, { tag: '全景' }, { tag: '固定' }] }
      if (c.clipId.startsWith('C0007')) return { clipId: c.clipId, tags: [{ tag: '测试图', confidence: 0.8 }, { tag: '推', confidence: 0.5 }, { tag: '中景' }, { tag: '芦苇', dim: '场景', confidence: 0.4 }] }
      return { clipId: c.clipId, tags: [{ tag: '测试图', confidence: 0.6 }] }
    })
    const tagged = await call('media_tag_clips', { items })
    assert.deepEqual(tagged.newPendingTags, ['芦苇'])
    assert.ok(tagged.lowConfidence >= 1)
    const ctx = await call('media_context')
    assert.deepEqual(ctx.dictionary.pending, ['芦苇（场景）'])
    assert.equal(ctx.tagTemplate.label, 'Vlog 基础')
    assert.equal(ctx.targetDuration, null)

    // Approval sentences (FR-42)
    const ask = await approvalFor(service, exec('media_tags_update', { op: 'rename', tag: '测试图', to: '测试画面' }))
    assert.match(ask, /更新 \d+ 条切片标签/)
    assert.equal(await approvalFor(service, exec('media_render', { kind: 'preview' })), null)

    // Review + rename propagate
    await service.media.review(root, 'C0001_s01', ['测试图', '全景', '固定'])
    const renamed = await service.tagOperation(id, { op: 'rename', tag: '测试图', to: '测试画面' })
    assert.ok(renamed.clips >= 3)
    const rep = await service.media.computeReport(root, (await service.open(id)).project)
    assert.equal(rep.tagging.adoption, 0.75, 'one of four AI tags removed in review')

    // Approve pending → dictionary + clip tags
    await service.tagOperation(id, { op: 'approve', tag: '芦苇', dim: '场景' })
    const dictAfter = await service.creative.read(root, '标签字典.yaml')
    assert.match(dictAfter.content, /场景: \[.*芦苇/)

    // Storyboard + match
    const sb = STORYBOARD.replaceAll('测试图', '测试画面')
    await call('media_creative_write', { file: '03_分镜脚本.md', content: sb })
    await service.creative.setEditUse(root, '03_分镜脚本.md')
    const m = await call('media_match')
    console.log(JSON.stringify(m.shots))
    const byNo = Object.fromEntries(m.shots.map((s) => [s.no, s]))
    assert.equal(byNo['01'].selected, 'C0001_s01')
    assert.equal(byNo['02'].selected, 'C0001_s02')
    assert.equal(byNo['05'].status, 'missing', 'shot without tags is never auto matched')
    const gaps = await call('media_gaps')
    assert.ok(gaps.count >= 1)
    assert.ok(existsSync(path.join(dir, '创意剪辑', '缺口清单.md')))

    // Spec + timeline + renders
    await call('media_edit_spec_set', { resolution: '1920x1080', fps: 25, codec: 'h264', bitrateMbps: 8, subtitles: 'burn+srt' })
    const tl = await call('media_timeline_build')
    assert.ok(tl.segments >= 3)
    const preview = await waitFor(await service.runStep(id, 'render-preview'))
    assert.equal(preview.status, 'done', preview.error)
    const final = await waitFor(await service.runStep(id, 'render-final'))
    assert.equal(final.status, 'done', final.error)
    const manifest = JSON.parse(await readFile(path.join(dir, '输出素材库', '成片', 'manifest.json'), 'utf8'))
    assert.equal(manifest.actual.width, 1920)
    assert.equal(manifest.actual.height, 1080)
    assert.equal(manifest.actual.fps, 25)
    assert.ok(manifest.durationError <= 0.5, `duration error ${manifest.durationError}`)
    assert.equal(manifest.versions.storyboard, 1)
    assert.ok(existsSync(path.join(dir, manifest.subtitles)))

    // Overview used by the panel
    const o = await service.overview(id)
    assert.equal(o.creative.docs.find((d) => d.key === '03_分镜脚本.md').editUse, 1)
    assert.ok(o.edit.exports.length >= 2)
    assert.equal(o.storyboard.warnings.length, 1)

    // Versioning: external modification is archived
    const { writeFile } = await import('node:fs/promises')
    await writeFile(path.join(dir, '创意剪辑', '02_文案.md'), '# 文案 v1\n第一版')
    let list = await service.creative.list(root)
    assert.equal(list.find((d) => d.key === '02_文案.md').version, 1)
    await writeFile(path.join(dir, '创意剪辑', '02_文案.md'), '# 文案\n第二版，被外部工具改写')
    list = await service.creative.list(root)
    const doc = list.find((d) => d.key === '02_文案.md')
    assert.equal(doc.version, 2)
    assert.ok(doc.history.some((h) => h.ref === 'v1'))
    await service.creative.write(root, '02_文案.md', '# 文案\n第二版，被外部工具改写\n用户手改一行', { source: 'manual' })
    const after = (await service.creative.list(root)).find((d) => d.key === '02_文案.md')
    assert.equal(after.version, 2)
    assert.equal(after.manualEdits, 1)
    const diff = await service.creative.diff(root, '02_文案.md', 'v1')
    assert.ok(diff.lines.some((l) => l.type === 'add'))
    await service.creative.rollback(root, '02_文案.md', 'v1')
    assert.equal((await service.creative.read(root, '02_文案.md')).content, '# 文案 v1\n第一版')

    // Safety: tools cannot escape the project
    await assert.rejects(() => service.fileFor(id, '../../etc/passwd'))
    await assert.rejects(() => service.fileFor(id, '创意剪辑/02_文案.md'))
    await assert.rejects(() => service.fileFor(id, '.dsh/index.json'))
  } finally {
    service.dispose()
    await rm(home, { recursive: true, force: true })
    await rm(dir, { recursive: true, force: true })
  }
})
